content.content:
1	/* ============================ Đi dạo: chuyển động nhân vật (thuần) ============================
2	   Mỗi khung: đọc đầu vào, đổi tốc độ / hướng mặt, nhảy, đi qua stMove (va chạm), bám cao độ đứng, chọn dáng (pose).
3	   Thuần: không import three, không đụng DOM. stStep chạy mỗi khung nên không cấp phát (D-018): dùng đối tượng tạm cấp module.
4	   - dt kẹp về dtMax: khung rất dài (tab ẩn rồi quay lại) không làm nhân vật vọt qua tường, chỉ chậm đi một khung.
5	   - Hướng: tới = (cos yaw, 0, −sin yaw), yaw tăng là quay trái (như flight.ts).
6	   - Cổng nhịp quay đóng dưới chân (vị trí không còn hợp lệ): stMove đóng băng khi điểm xuất phát không hợp lệ, nên sơ tán KHÔNG dùng stMove:
7	     tính một lần điểm hợp lệ gần nhất (stNearestValid, đắt), rồi đi thẳng tới đó với tốc độ chạy, bỏ qua đầu vào; tới nơi thì trả điều khiển. */
8	import { CONFIG } from '../../config';
9	import { stMove, stValid, stGroundY, stNearestValid, type StMap } from './map';
10	import { stSpawn } from './mapData';
11	
12	export const ST_POSE_IDLE = 0, ST_POSE_WALK = 1, ST_POSE_RUN = 2, ST_POSE_JUMP = 3, ST_POSE_PHOTO = 4;
13	
14	export interface StState {
15	  x: number; y: number; z: number;   // y: cao độ chân tuyệt đối, m
16	  yaw: number; speed: number;        // speed: tốc độ mặt bằng, m/s
17	  vy: number; air: boolean;          // vy: vận tốc đứng, m/s
18	  pose: number; evac: boolean;
19	  photo: number;                     // giây còn giơ tay chụp
20	  tx: number; tz: number;            // điểm sơ tán đã tính (chỉ có nghĩa khi evac)
21	}
22	export interface StInput { mx: number; mz: number; run: boolean; jump: boolean; camYaw: number }
23	
24	const EPS_STEP = 1e-3;      // dung sai khi so bậc cao độ với stepMax (bậc Cầu Rồng lề ↔ bờ đo 0,3500083), m
25	const V_STOP = 0.1;         // m/s — dưới mức này coi là đứng yên
26	const _mv = { x: 0, z: 0 };      // kết quả stMove
27	const _near = { x: 0, z: 0 };    // kết quả stNearestValid
28	
29	export function stCreate(map: StMap, slot: number): StState {
30	  const p = { x: 0, z: 0 };
31	  stSpawn(map, slot, p);
32	  const g = stGroundY(map, p.x, p.z);
33	  return { x: p.x, y: g === g ? g : CONFIG.roadY, z: p.z, yaw: CONFIG.stroll.spawnYaw, speed: 0, vy: 0, air: false, pose: ST_POSE_IDLE, evac: false, photo: 0, tx: p.x, tz: p.z };
34	}
35	
36	export function stPhotoPose(s: StState): void { s.photo = CONFIG.stroll.photoHold; }
37	
38	/* quay yaw về đích theo đường ngắn nhất, tốc độ mũ turn (1/s) */
39	function stTurn(yaw: number, target: number, turn: number, dt: number): number {
40	  let d = (target - yaw) % (2 * Math.PI);
41	  if (d > Math.PI) d -= 2 * Math.PI; else if (d < -Math.PI) d += 2 * Math.PI;
42	  const k = turn * dt;
43	  return yaw + d * (k < 1 ? k : 1);
44	}
45	
46	/* Sơ tán: đi thẳng tới (tx, tz) với tốc độ chạy, mỗi khung không quá run × dt */
47	function stEvacStep(s: StState, map: StMap, dt: number): void {
48	  const C = CONFIG.stroll, dx = s.tx - s.x, dz = s.tz - s.z, dist = Math.sqrt(dx * dx + dz * dz), step = C.run * dt;
49	  s.photo = 0; s.speed = C.run; s.pose = ST_POSE_RUN;
50	  if (dist > 1e-9) s.yaw = stTurn(s.yaw, Math.atan2(-dz, dx), C.turn, dt);
51	  if (dist <= step) { s.x = s.tx; s.z = s.tz; s.evac = false; s.speed = 0; s.pose = ST_POSE_IDLE; }
52	  else { s.x += dx / dist * step; s.z += dz / dist * step; }
53	  const g = stGroundY(map, s.x, s.z);
54	  if (g === g) s.y = g;                                  // ngoài mọi vùng (cổng đóng): giữ cao độ cũ
55	  s.air = false; s.vy = 0;
56	}
57	
58	export function stStep(s: StState, inp: StInput, map: StMap, dt: number): void {
59	  const C = CONFIG.stroll;
60	  if (!(dt > 0)) return;
61	  if (dt > C.dtMax) dt = C.dtMax;
62	
63	  /* 1) vị trí không còn hợp lệ với tường cao / vùng (tường thấp không tính: đáp xuống giữa tường thấp là chuyện của stMove) */
64	  if (!s.evac && !stValid(map, s.x, s.z, Infinity)) {
65	    s.evac = true;
66	    if (!stNearestValid(map, s.x, s.z, _near)) stSpawn(map, -1, _near);
67	    s.tx = _near.x; s.tz = _near.z;
68	  }
69	  if (s.evac) { stEvacStep(s, map, dt); return; }
70	
71	  /* 2) hướng đi và tốc độ đích */
72	  const sc = Math.sin(inp.camYaw), cc = Math.cos(inp.camYaw);
73	  const dx = inp.mz * cc + inp.mx * sc, dz = -inp.mz * sc + inp.mx * cc;
74	  let len = Math.sqrt(dx * dx + dz * dz);
75	  const moving = len > 1e-6;
76	  if (len > 1) len = 1;
77	  const target = moving ? (inp.run ? C.run : C.walk) * len : 0;
78	  const da = C.accel * dt;
79	  if (s.speed < target) s.speed = s.speed + da < target ? s.speed + da : target;
80	  else s.speed = s.speed - da > target ? s.speed - da : target;
81	  let hx: number, hz: number;                            // hướng di chuyển: theo đầu vào; thả tay thì trượt theo hướng mặt đang hãm
82	  if (moving) { hx = dx / Math.sqrt(dx * dx + dz * dz); hz = dz / Math.sqrt(dx * dx + dz * dz); s.yaw = stTurn(s.yaw, Math.atan2(-hz, hx), C.turn, dt); }
83	  else { hx = Math.cos(s.yaw); hz = -Math.sin(s.yaw); }
84	
85	  /* 3) nhảy: chỉ khi chạm đất */
86	  if (!s.air && inp.jump) { s.vy = Math.sqrt(2 * C.gravity * C.jumpHeight); s.air = true; }
87	
88	  /* 4) đi (feet: độ cao chân trên cao độ đứng chỗ đang đứng) */
89	  const g0 = stGroundY(map, s.x, s.z);
90	  const feet = s.air && g0 === g0 ? Math.max(0, s.y - g0) : 0;
91	  const dist = s.speed * dt;
92	  stMove(map, s.x, s.z, hx * dist, hz * dist, feet, _mv);
93	  s.x = _mv.x; s.z = _mv.z;
94	
95	  /* 5) cao độ */
96	  const g = stGroundY(map, s.x, s.z);
97	  if (s.air) {
98	    const ny = s.y + s.vy * dt - 0.5 * C.gravity * dt * dt;
99	    s.vy -= C.gravity * dt;
100	    if (g === g && ny <= g) {                            // chạm đất
101	      s.y = g; s.vy = 0; s.air = false;
102	      if (!stValid(map, s.x, s.z, 0) && stNearestValid(map, s.x, s.z, _near)) { s.x = _near.x; s.z = _near.z; const g2 = stGroundY(map, s.x, s.z); if (g2 === g2) s.y = g2; }   // đáp giữa tường thấp: đẩy ra mép gần nhất
103	    } else s.y = ny;
104	  } else if (g === g) {
105	    if (s.y - g > C.stepMax + EPS_STEP) { s.air = true; s.vy = 0; }   // bước xuống quá bậc: rơi
106	    else s.y = g;
107	  }
108	
109	  /* 6) dáng */
110	  if (s.photo > 0) { if (moving || s.air) s.photo = 0; else { s.photo -= dt; if (s.photo < 0) s.photo = 0; } }
111	  const still = s.speed < V_STOP && !moving;
112	  if (s.air) s.pose = ST_POSE_JUMP;
113	  else if (s.photo > 0 && still) s.pose = ST_POSE_PHOTO;
114	  else if (s.speed < V_STOP) s.pose = ST_POSE_IDLE;
115	  else s.pose = s.speed > (C.walk + C.run) * 0.5 ? ST_POSE_RUN : ST_POSE_WALK;
116	}
