1	/* ============================ Đi dạo: điều phối chế độ (một mình hoặc nhiều người, máy tính) ============================
2	   Nối bản đồ va chạm (map / mapData / sceneData), chuyển động (motion), nhân vật (avatars), camera sau lưng (camera) với vòng animate, phím, chuột.
3	   `?explore=stroll` vào thẳng, đi một mình (explore/index.ts gọi start). Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020).
4	   - Bản đồ dựng lần đầu vào chế độ: dữ liệu tĩnh + nhà / chân đế thu từ cảnh đã dựng (chỉ đọc, sau mọi rand()).
5	   - Nhịp quay Cầu sông Hàn đóng với người đi dạo khi cầu rời trạng thái CLOSED (spec §3 mục 13); không tự quay, không tăng tốc quay.
6	   - Ban đêm Cầu Rồng tự phun như khi bay dù (exNightStep, không đụng cầu quay).
7	   - Nhảy theo cạnh: một lần bấm Space một lần nhảy, giữ Space không nhảy liên tục (stStep nhảy mỗi khung jump = true khi chạm đất).
8	   - Phím chỉ ghi khi đang đi dạo, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì xóa hết phím (Review Focus 3).
9	   - Nhiều người (exMulti, phiên kind 'walk'): xuất phát theo slot đi dạo, gửi vị trí + dáng; hết chỗ thì chế độ xem (startWatching) đặt camera sau lưng người được xem.
10	     Đổi phiên như dù lượn: bị thu chỗ → xem; mất kết nối khi đang đi → đi tiếp một mình + thông báo; mất kết nối khi xem → thoát, màn chọn báo mất kết nối.
11	   - Rời máy: phím điều khiển, kéo chuột và chạm cảm ứng gọi exMulti.activity().
12	   - Cảm ứng (touch.ts, #stHud): cần gạt ghi đè phím khi đang được giữ; vuốt nửa phải xoay camera; chạm Nhảy là một lần nhảy (như một lần bấm Space); 📷 và phím P gọi stPhoto (photo.ts: chụp canvas sau lệnh vẽ chính).
13	   Mỗi khung không cấp phát (D-018). */
14	import { scene, camera, controls, canvas } from '../../core/renderer';
15	import { cam, keys } from '../../views/state';
16	import { CONFIG } from '../../config';
17	import { stSetGate, type StMap } from './map';
18	import { ST_GATE_SWING, stBuildStaticMap } from './mapData';
19	import { stCreate, stStep, stPhotoPose, type StState, type StInput } from './motion';
20	import { stPhotoRequest, stPhotoAfterRender, stPhotoLast } from './photo';
21	import { stAvatars } from './avatars';
22	import { stCollectRuntime } from './sceneData';
23	import { stCamPlace, stCamDrag, type StCam } from './camera';
24	import { stInputFromKeys, stKeyName } from './keys';
25	import { stTouchBind } from './touch';
26	import { exNightStep } from '../nightShows';
27	import { exMulti } from '../multi';
28	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
29	import type { SwingController } from '../../bridges/song-han/SwingController';
30	
31	const ST_SOLO_SLOT = -1;     // stCreate / stSpawn: đi một mình đứng giữa các điểm xuất phát
32	const ST_SOLO_AVATAR = 0;    // instance nhân vật khi đi một mình (avatars.ts)
33	
34	let map: StMap | null = null;
35	let state: StState | null = null;
36	let ctrl: SwingController | null = null;
37	let exit: () => void = () => {};   // thoát chung (explore.exit), do setupStroll nhận
38	let jumpQueued = false;      // Space vừa được bấm (không phải tự lặp): khung sau nhảy một lần
39	let selfSlot = ST_SOLO_AVATAR;   // instance nhân vật của mình: slot đi dạo khi có chỗ, giữ nguyên khi mất kết nối (màu áo không đổi)
40	let watching = false;        // đang xem người khác đi dạo (hết chỗ hoặc vừa nhường chỗ): không có nhân vật của mình, không đọc phím
41	let touch: ReturnType<typeof stTouchBind> | null = null;   // điều khiển cảm ứng (setupStroll dựng)
42	let chased = false;          // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
43	const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
44	const _inp: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung
45	
46	const active = () => cam.mode === 'stroll' && state !== null;
47	const inMode = () => active() || watching;   // Esc và giao diện đi dạo áp cho cả chế độ xem
48	/* Chụp ảnh (nút 📷, phím P): giơ tay (dáng 4, tới người khác qua gói vị trí kế tiếp), chớp màn hình, xếp yêu cầu chụp cho sau lệnh vẽ */
49	let flashTimer = 0;
50	function stPhoto(): void {
51	  if (!active()) return;
52	  stPhotoPose(state!);
53	  const f = document.getElementById('stFlash');
54	  if (f) { f.classList.add('on'); clearTimeout(flashTimer); flashTimer = window.setTimeout(() => f.classList.remove('on'), CONFIG.stroll.flashMs); }
55	  stPhotoRequest();
56	}
57	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
58	
59	/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
60	function advance(dt: number, inp: StInput): void {
61	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
62	  stStep(state!, inp, map!, dt);
63	  stAvatars.setSelf(selfSlot, state);
64	  stCamPlace(camera, controls.target, state!, camS, map!, dt);
65	  exNightStep(dt, false);
66	  const now = performance.now();
67	  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
68	  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
69	}
70	
71	/* Mỗi khung khi xem: người khác, nhãn, danh sách; camera sau lưng người được xem (hướng camera = hướng mặt họ). Không có ai thì camera giữ nguyên */
72	function watchStep(dt: number): void {
73	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
74	  exMulti.update(dt, performance.now(), null);
75	  const w = exMulti.watchWalker();
76	  if (w) { camS.yaw = w.yaw; stCamPlace(camera, controls.target, w, camS, map!, dt, !chased); chased = true; }
77	  exNightStep(dt, false);
78	}
79	
80	/* Đổi phiên khi đang xem hoặc đang đi: vào đi, mất kết nối, bị thu hồi chỗ (như onMultiChange của dù lượn) */
81	function stOnMultiChange(): void {
82	  const s = exMulti.session; if (!s) return;
83	  if (watching) {
84	    if (s.phase === 'flying') { stroll.start(); return; }   // chấp nhận lời mời: xuất phát như vào đi thường
85	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostWalk'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện stLostChooser (nhắc Đi dạo, không phải Dù lượn)
86	    exWatchRender();
87	  } else if (active()) {
88	    if (s.phase === 'watching') { state = null; stAvatars.setSelf(selfSlot, null); stroll.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
89	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'stLost');   // vẫn đi, người khác đã biến mất
90	  }
91	}
92	
93	/* Bản đồ dựng lần đầu vào chế độ (đi hoặc xem); cổng nhịp quay theo cầu hiện tại */
94	function stEnsureMap(): StMap {
95	  if (!map) { map = stBuildStaticMap(); stCollectRuntime(map); }
96	  if (ctrl) stSetGate(map, ST_GATE_SWING, ctrl.state !== 'CLOSED');
97	  return map;
98	}
99	
100	export const stroll = {
101	  active,
102	  inMode,
103	  get watching(): boolean { return watching; },
104	  get state(): StState | null { return state; },
105	  get map(): StMap | null { return map; },
106	  get cam(): StCam { return camS; },
107	  /* Vào đi: một mình (không phiên / ngoại tuyến) hoặc với slot đi dạo vừa được cấp (xuất phát lệch theo slot) */
108	  start(): void {
109	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
110	    const m = stEnsureMap(), s = exMulti.session;
111	    const slot = s && s.kind === 'walk' && s.mySlot >= 0 ? s.mySlot : ST_SOLO_SLOT;
112	    if (s) exMulti.onChange = stOnMultiChange;
113	    selfSlot = slot >= 0 ? slot : ST_SOLO_AVATAR;
114	    state = stCreate(m, slot);
115	    camS.yaw = state.yaw; camS.pitch = CONFIG.stroll.cam.pitch;
116	    const mesh = stAvatars.build();
117	    if (!mesh.parent) scene.add(mesh);
118	    stAvatars.setSelf(selfSlot, state);
119	    keys.clear(); jumpQueued = false; if (touch) touch.reset();
120	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
121	    stCamPlace(camera, controls.target, state, camS, m, 0, true);
122	    document.body.classList.add('explore', 'stroll');
123	  },
124	  /* Chế độ xem: cam.mode = 'stroll' nhưng không có nhân vật của mình; carry = true khi vừa nhường chỗ (camera đang ở sau lưng mình, trượt dần sang người được xem) */
125	  startWatching(carry = false): void {
126	    const s = exMulti.session; if (!s) return;
127	    stEnsureMap();
128	    const mesh = stAvatars.build();
129	    if (!mesh.parent) scene.add(mesh);
130	    watching = true; chased = carry; state = null;
131	    keys.clear(); jumpQueued = false;
132	    camS.pitch = CONFIG.stroll.cam.pitch;
133	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
134	    document.body.classList.add('explore', 'stroll', 'ex-watching');
135	    exMulti.onChange = stOnMultiChange;
136	    exWatchShow(s);
137	  },
138	  update(dt: number): void {
139	    if (watching) { watchStep(dt); return; }
140	    if (!active()) return;
141	    stInputFromKeys(keys, camS.yaw, _inp);
142	    if (touch) touch.read(_inp);   // cần gạt đang giữ thì ghi đè hướng và chạy của phím
143	    _inp.jump = jumpQueued; jumpQueued = false;
144	    advance(dt, _inp);
145	  },
146	  photo: stPhoto,
147	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts): chụp canvas nếu có yêu cầu */
148	  afterRender(): void { stPhotoAfterRender(canvas); },
149	  get photoLast() { return stPhotoLast; },
150	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
151	  step(dt: number, inp: StInput): void {
152	    if (active()) advance(dt, inp);
153	  }
154	};
155	
156	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
157	export function setupStroll(c: SwingController, onExit: () => void): void {
158	  ctrl = c; exit = onExit;
159	  window.addEventListener('keydown', (e) => {
160	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung); đang xem: không đọc phím
161	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển nhân vật, tránh kẹt phím
162	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển nhân vật
163	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
164	    const k = stKeyName(e);   // theo vị trí phím (e.code): bố cục không Latin (ru, ar, th, hi) vẫn dùng WASD
165	    if (k === 'p') { if (!e.repeat) stPhoto(); return; }   // P chụp ảnh, không ghi vào keys
166	    if (k === ' ') { e.preventDefault(); if (!e.repeat) jumpQueued = true; }
167	    else if (k.startsWith('arrow')) e.preventDefault();
168	    keys.add(k);
169	  });
170	  window.addEventListener('keyup', (e) => {
171	    const k = stKeyName(e);
172	    keys.delete(k); keys.delete(e.key.toLowerCase());   // cả tên cũ: phím dù lượn ghi theo e.key
173	    if (k === ' ' && active() && !isField(e.target)) e.preventDefault();   // Space không bấm nút đang focus
174	  });
175	  const drop = () => { keys.clear(); jumpQueued = false; };
176	  window.addEventListener('blur', drop);
177	  document.addEventListener('visibilitychange', () => { if (document.hidden) drop(); });
178	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
179	  const hud = document.getElementById('stHud');
180	  if (hud) touch = stTouchBind(hud, {
181	    look: (dx, dy) => { if (active()) stCamDrag(camS, dx, dy, CONFIG.stroll.cam.touch); },
182	    jump: () => { if (active()) jumpQueued = true; },
183	    photo: stPhoto,
184	    activity: () => exMulti.activity()
185	  });
186	  /* Kéo chuột trái trên canvas: xoay camera (cảm ứng ở Task 8) */
187	  let dragId = -1, lx = 0, ly = 0;
188	  canvas.addEventListener('pointerdown', (e) => {
189	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
190	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
191	    canvas.setPointerCapture(e.pointerId);
192	  });
193	  canvas.addEventListener('pointermove', (e) => {
194	    if (e.pointerId !== dragId) return;
195	    stCamDrag(camS, e.clientX - lx, e.clientY - ly, CONFIG.stroll.cam.mouse);
196	    exMulti.activity();   // xoay camera cũng tính là còn đó
197	    lx = e.clientX; ly = e.clientY;
198	  });
199	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
200	  canvas.addEventListener('pointerup', end);
201	  canvas.addEventListener('pointercancel', end);
202	  canvas.addEventListener('lostpointercapture', end);
203	}
