1	/* ============================ Đi dạo: đầu vào từ bàn phím (thuần) ============================
2	   W/↑ tới, S/↓ lùi, A/← trái, D/→ phải theo hướng camera; chéo chuẩn hóa về độ dài 1; Shift chạy; Space nhảy.
3	   Nhảy ở đây chỉ phản ánh phím đang giữ: index.ts biến nó thành một lần nhảy mỗi lần bấm (stStep nhảy mỗi khung jump = true khi chạm đất).
4	   Không cấp phát (gọi mỗi khung). */
5	import type { StInput } from './motion';
6	
7	/* Tên phím chuẩn theo vị trí vật lý (e.code) để bố cục không Latin (ru, ar, th, hi) vẫn dùng được WASD / P / Shift / Space; không có code thì dùng e.key. Chỉ đi dạo dùng, phím dù lượn giữ nguyên. */
8	const ST_CODE_KEY: Record<string, string> = { KeyW: 'w', KeyA: 'a', KeyS: 's', KeyD: 'd', KeyP: 'p', ShiftLeft: 'shift', ShiftRight: 'shift', Space: ' ' };
9	export function stKeyName(e: { key: string; code?: string }): string {
10	  return (e.code && ST_CODE_KEY[e.code]) || e.key.toLowerCase();
11	}
12	
13	export function stInputFromKeys(keys: Set<string>, camYaw: number, out: StInput): StInput {
14	  let f = 0, r = 0;
15	  if (keys.has('w') || keys.has('arrowup')) f += 1;
16	  if (keys.has('s') || keys.has('arrowdown')) f -= 1;
17	  if (keys.has('d') || keys.has('arrowright')) r += 1;
18	  if (keys.has('a') || keys.has('arrowleft')) r -= 1;
19	  const len = Math.sqrt(f * f + r * r);
20	  if (len > 1) { f /= len; r /= len; }
21	  out.mz = f; out.mx = r; out.run = keys.has('shift'); out.jump = keys.has(' '); out.camYaw = camYaw;
22	  return out;
23	}
