1	/* ============================ Đi dạo: điều khiển cảm ứng ============================
2	   Ba con trỏ độc lập trên #stHud: cần gạt #stPad (ngón trái), vuốt #stLook (nửa phải, dưới các nút), nút #stJump; #stPhoto là nút bấm thường (cả máy tính).
3	   - Mỗi vùng chỉ theo con trỏ đã chạm vào nó (pointerId riêng + setPointerCapture), nên giữ cần gạt, vuốt camera và chạm Nhảy cùng lúc không lẫn nhau.
4	   - Nhảy theo cạnh: một lần chạm gọi jump() một lần (stStep nhảy lại ngay khi chạm đất nếu jump còn giữ).
5	   - Thả tay, pointercancel, lostpointercapture, blur, ẩn tab, xoay màn hình, đổi cỡ khung nhìn đáng kể: reset() — cần gạt về giữa, nhân vật dừng (Review Focus 2).
6	   - read(out) chỉ ghi đè mx / mz / run khi cần gạt đang được giữ (cảm ứng ưu tiên phím) và, khi đang giữ, báo activity() mỗi activityMs (giữ yên ngón tay không phát sự kiện); mỗi khung không cấp phát (D-018). */
7	import { CONFIG } from '../../config';
8	import { stStick } from './stick';
9	import type { StInput } from './motion';
10	
11	export interface StTouchHandlers { look(dxPx: number, dyPx: number): void; jump(): void; photo(): void; activity(): void }
12	
13	export function stTouchBind(root: HTMLElement, h: StTouchHandlers): { read(out: StInput): void; reset(): void } {
14	  const pad = root.querySelector<HTMLElement>('#stPad'), knob = root.querySelector<HTMLElement>('#stKnob');
15	  const look = root.querySelector<HTMLElement>('#stLook'), jump = root.querySelector<HTMLElement>('#stJump'), photo = root.querySelector<HTMLElement>('#stPhoto');
16	  const size = CONFIG.stroll.stick.size;
17	  root.style.setProperty('--st-pad', size + 'px');   // đường kính cần gạt lấy từ CONFIG
18	  let padId = -1, cx = 0, cy = 0, dx = 0, dy = 0, r = size / 2;   // cần gạt: con trỏ, tâm (px màn hình, chốt lúc chạm), độ lệch núm
19	  let padW = 0, padH = 1, lastAct = 0;                             // cỡ khung nhìn lúc chạm cần gạt, lần báo "còn đó" gần nhất (ms)
20	  let lookId = -1, lx = 0, ly = 0;                               // vuốt camera: con trỏ, vị trí trước
21	  let jumpId = -1;
22	  const own = (el: HTMLElement, e: PointerEvent) => { try { el.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động (sự kiện giả) */ } };
23	
24	  const knobTo = (x: number, y: number) => { if (knob) knob.style.transform = x === 0 && y === 0 ? '' : `translate(${x}px,${y}px)`; };
25	  const reset = () => { padId = -1; lookId = -1; jumpId = -1; dx = 0; dy = 0; knobTo(0, 0); };
26	
27	  if (pad) {
28	    pad.addEventListener('pointerdown', (e) => {
29	      if (padId >= 0) return;
30	      e.preventDefault();
31	      const b = pad.getBoundingClientRect();
32	      cx = b.left + b.width / 2; cy = b.top + b.height / 2; r = b.width / 2 || size / 2;
33	      padId = e.pointerId; padW = window.innerWidth; padH = window.innerHeight; lastAct = performance.now(); own(pad, e); h.activity();
34	      pad.dispatchEvent(new PointerEvent('pointermove', { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY }));   // núm theo ngón ngay lúc chạm
35	    });
36	    pad.addEventListener('pointermove', (e) => {
37	      if (e.pointerId !== padId) return;
38	      dx = e.clientX - cx; dy = e.clientY - cy;
39	      const d = Math.sqrt(dx * dx + dy * dy);
40	      if (d > r) { dx = dx / d * r; dy = dy / d * r; }   // núm không ra khỏi vòng
41	      knobTo(dx, dy); h.activity();
42	    });
43	    const padEnd = (e: PointerEvent) => { if (e.pointerId === padId) { padId = -1; dx = 0; dy = 0; knobTo(0, 0); } };
44	    pad.addEventListener('pointerup', padEnd);
45	    pad.addEventListener('pointercancel', padEnd);
46	    pad.addEventListener('lostpointercapture', padEnd);
47	  }
48	
49	  if (look) {
50	    look.addEventListener('pointerdown', (e) => {
51	      if (lookId >= 0) return;
52	      e.preventDefault();
53	      lookId = e.pointerId; lx = e.clientX; ly = e.clientY; own(look, e); h.activity();
54	    });
55	    look.addEventListener('pointermove', (e) => {
56	      if (e.pointerId !== lookId) return;
57	      h.look(e.clientX - lx, e.clientY - ly); h.activity();
58	      lx = e.clientX; ly = e.clientY;
59	    });
60	    const lookEnd = (e: PointerEvent) => { if (e.pointerId === lookId) lookId = -1; };
61	    look.addEventListener('pointerup', lookEnd);
62	    look.addEventListener('pointercancel', lookEnd);
63	    look.addEventListener('lostpointercapture', lookEnd);
64	  }
65	
66	  if (jump) {
67	    jump.addEventListener('pointerdown', (e) => {
68	      e.preventDefault();
69	      if (jumpId < 0) { jumpId = e.pointerId; own(jump, e); h.jump(); h.activity(); }   // một lần chạm một lần nhảy
70	    });
71	    const jumpEnd = (e: PointerEvent) => { if (e.pointerId === jumpId) jumpId = -1; };
72	    jump.addEventListener('pointerup', jumpEnd);
73	    jump.addEventListener('pointercancel', jumpEnd);
74	    jump.addEventListener('lostpointercapture', jumpEnd);
75	  }
76	
77	  if (photo) photo.addEventListener('click', () => { h.activity(); h.photo(); });   // chuột và chạm đều ra click
78	
79	  window.addEventListener('blur', reset);
80	  document.addEventListener('visibilitychange', () => { if (document.hidden) reset(); });
81	  window.addEventListener('orientationchange', reset);
82	  /* Thanh địa chỉ điện thoại co giãn làm đổi innerHeight nhẹ: chỉ thả cần gạt khi bề rộng đổi hoặc bề cao đổi quá resizeKeep */
83	  window.addEventListener('resize', () => {
84	    if (padId < 0 || window.innerWidth !== padW || Math.abs(window.innerHeight - padH) > padH * CONFIG.stroll.stick.resizeKeep) reset();
85	  });
86	
87	  return {
88	    read(out: StInput): void {
89	      if (padId < 0) return;
90	      stStick(dx, dy, r, out);
91	      const now = performance.now();   // giữ yên cần gạt không phát sự kiện: báo "còn đó" thưa, không cấp phát
92	      if (now - lastAct >= CONFIG.stroll.stick.activityMs) { lastAct = now; h.activity(); }
93	    },
94	    reset
95	  };
96	}
97

};

