/* ===== Đi dạo: tên phím theo vị trí vật lý (src/explore/stroll/keys.ts) — bố cục không Latin vẫn dùng WASD ===== */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { stKeyName, stInputFromKeys } from '../../src/explore/stroll/keys.ts';

test('phím theo e.code, bất kể chữ trên phím (ru, ar, th, hi)', () => {
  assert.equal(stKeyName({ key: 'ц', code: 'KeyW' }), 'w');      // ru
  assert.equal(stKeyName({ key: 'ش', code: 'KeyA' }), 'a');      // ar
  assert.equal(stKeyName({ key: 'ห', code: 'KeyS' }), 's');      // th
  assert.equal(stKeyName({ key: 'व', code: 'KeyD' }), 'd');      // hi
  assert.equal(stKeyName({ key: 'з', code: 'KeyP' }), 'p');
  assert.equal(stKeyName({ key: 'Shift', code: 'ShiftRight' }), 'shift');
  assert.equal(stKeyName({ key: ' ', code: 'Space' }), ' ');
});

test('không có code (sự kiện giả) hoặc phím khác: dùng e.key viết thường', () => {
  assert.equal(stKeyName({ key: 'W' }), 'w');
  assert.equal(stKeyName({ key: 'ArrowUp', code: 'ArrowUp' }), 'arrowup');
  assert.equal(stKeyName({ key: 'Shift', code: '' }), 'shift');
});

test('bố cục Nga: phím vật lý W cho đi tới', () => {
  const out = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
  stInputFromKeys(new Set([stKeyName({ key: 'ц', code: 'KeyW' })]), 0, out);
  assert.equal(out.mz, 1);
});
/* ===== Đi dạo: cần gạt cảm ứng giữ yên vẫn báo "còn đó", đổi cỡ khung nhìn nhẹ không thả cần gạt (src/explore/stroll/touch.ts) ===== */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { CONFIG } from '../../src/config.ts';

/* Giả DOM tối thiểu: phần tử lưu các hàm nghe, dispatchEvent gọi lại đúng loại sự kiện */
class FakeEl {
  handlers: Record<string, ((e: any) => void)[]> = {};
  style = { setProperty() {}, transform: '' };
  addEventListener(type: string, fn: (e: any) => void) { (this.handlers[type] ||= []).push(fn); }
  dispatchEvent(e: any) { (this.handlers[e.type] || []).forEach((fn) => fn(e)); return true; }
  setPointerCapture() {}
  getBoundingClientRect() { return { left: 0, top: 0, width: 120, height: 120 }; }
}
const els: Record<string, FakeEl> = {};
const root = { style: { setProperty() {} }, querySelector: (s: string) => (els[s] ||= new FakeEl()) };
const win = new FakeEl() as any; win.innerWidth = 400; win.innerHeight = 800;
(globalThis as any).window = win;
(globalThis as any).document = new FakeEl();
(globalThis as any).PointerEvent = class { constructor(public type: string, init: any) { Object.assign(this, init); } };
let now = 0;
Object.defineProperty(globalThis, 'performance', { value: { now: () => now }, configurable: true });
const { stTouchBind } = await import('../../src/explore/stroll/touch.ts');

let acts = 0;
const t = stTouchBind(root as any, { look() {}, jump() {}, photo() {}, activity() { acts++; } });
const out = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
const down = () => els['#stPad'].dispatchEvent({ type: 'pointerdown', pointerId: 1, clientX: 60, clientY: 10, preventDefault() {} });
const resize = () => win.dispatchEvent({ type: 'resize' });
const held = () => { out.mz = 0; t.read(out); return out.mz !== 0 || out.mx !== 0; };

test('giữ yên cần gạt: báo còn đó thưa, mỗi activityMs một lần', () => {
  now = 5000; down();
  const a0 = acts;
  for (let i = 0; i < 20; i++) { now += 16; t.read(out); }   // 320 ms: chưa tới hạn
  assert.equal(acts, a0, 'chưa tới activityMs thì chưa báo');
  now += CONFIG.stroll.stick.activityMs; t.read(out);
  assert.equal(acts, a0 + 1);
  t.read(out);
  assert.equal(acts, a0 + 1, 'đọc lại ngay không báo thêm');
  now += CONFIG.stroll.stick.activityMs; t.read(out);
  assert.equal(acts, a0 + 2);
  t.reset();
});

test('không giữ cần gạt: read không báo', () => {
  const a0 = acts; now += 10000; t.read(out);
  assert.equal(acts, a0);
});

test('đổi bề cao nhẹ (thanh địa chỉ) không thả cần gạt; đổi bề rộng hoặc bề cao lớn thì thả', () => {
  down(); assert.equal(held(), true);
  win.innerHeight = 800 - 40; resize();   // 5 % < resizeKeep
  assert.equal(held(), true, 'đổi 5 % bề cao: vẫn giữ');
  win.innerHeight = 800 - 200; resize();   // 25 %
  assert.equal(held(), false, 'đổi 25 % bề cao: thả');
  win.innerHeight = 800; down(); assert.equal(held(), true);
  win.innerWidth = 401; resize();
  assert.equal(held(), false, 'đổi bề rộng: thả');
  win.innerWidth = 400; down(); assert.equal(held(), true);
  win.dispatchEvent({ type: 'orientationchange' });
  assert.equal(held(), false, 'xoay màn hình: luôn thả');
});
/* ===== Đi dạo: test nhân vật hiển thị (src/explore/stroll/avatars.ts) và nội suy dáng bậc thang (ExTrack.sample step) ===== */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { CONFIG } from '../../src/config.ts';
import { ppAmp } from '../../src/common/people/gait.ts';
import { PP_FLAG } from '../../src/common/people/kinds.ts';
import { ExTrack } from '../../src/explore/multi/interp.ts';
import { stAvatarVar } from '../../src/explore/stroll/avatars.ts';
import { ST_POSE_IDLE, ST_POSE_WALK, ST_POSE_RUN, ST_POSE_JUMP, ST_POSE_PHOTO } from '../../src/explore/stroll/motion.ts';

const cap = CONFIG.stroll.cadenceMax * CONFIG.people.run.cadence;
const v = () => ({ amp: -1, cadence: -1, flags: -1 });

test('stAvatarVar: 5 dáng cho đúng biên độ và cờ', () => {
  const o = v();
  stAvatarVar(ST_POSE_IDLE, 0, o); assert.equal(o.amp, 0); assert.equal(o.flags, 0);
  stAvatarVar(ST_POSE_WALK, CONFIG.stroll.walk, o); assert.equal(o.amp, ppAmp('walk')); assert.equal(o.flags, 0);
  stAvatarVar(ST_POSE_RUN, CONFIG.stroll.run, o); assert.equal(o.amp, ppAmp('run')); assert.equal(o.flags, 0);
  stAvatarVar(ST_POSE_JUMP, CONFIG.stroll.walk, o); assert.equal(o.flags & PP_FLAG.jump, PP_FLAG.jump); assert.equal(o.flags & PP_FLAG.photo, 0);
  stAvatarVar(ST_POSE_PHOTO, 0, o); assert.equal(o.amp, 0); assert.equal(o.flags & PP_FLAG.photo, PP_FLAG.photo); assert.equal(o.flags & PP_FLAG.jump, 0);
  assert.equal(PP_FLAG.jump, 8);
});

test('tốc độ 10 m/s: nhịp = cadenceMax × run.cadence (bị kẹp)', () => {
  const o = v(); stAvatarVar(ST_POSE_RUN, 10, o);
  assert.ok(Math.abs(o.cadence - cap) < 1e-9, `${o.cadence} ≠ ${cap}`);
});

test('tốc độ 3,5 m/s: nhịp ≤ trần và > 0', () => {
  for (const pose of [ST_POSE_WALK, ST_POSE_RUN]) {
    const o = v(); stAvatarVar(pose, 3.5, o);
    assert.ok(o.cadence > 0 && o.cadence <= cap + 1e-9, `pose ${pose}: ${o.cadence}`);
  }
});

test('ExTrack.sample(step = true): dáng 1 rồi 4 trả 1 ở giữa khoảng, 4 từ mẫu sau', () => {
  const t = new ExTrack(); t.push(0, 0, 0, 0, 0, 1); t.push(100, 10, 0, 0, 0, 4);
  const o = { x: 0, y: 0, z: 0, yaw: 0, bank: 0 };
  assert.equal(t.sample(50, o, true), true); assert.equal(o.bank, 1); assert.ok(Math.abs(o.x - 5) < 1e-9, 'vị trí vẫn nội suy');
  t.sample(99.9, o, true); assert.equal(o.bank, 1);
  for (const amp of [0, P.walk.amp, P.run.amp]) for (const part of ['legL', 'legR', 'armL', 'armR'] as const) {
    const a0 = ppAngles(part, amp, 0, true);
    for (const f of phases) { const a = ppAngles(part, amp, f, true); assert.ok(a.root === a0.root && a.joint === a0.joint, `${part} amp ${amp} φ ${f}`); }
    if (part === 'legL' || part === 'legR') assert.ok(a0.joint < -0.6, `${part} gối ${a0.joint}`);
    else assert.ok(a0.root > 0.8, `${part} vai ${a0.root}`);
  }
});

test('jump = false (mặc định) giữ nguyên dáng cũ', () => {
  for (const amp of [0, P.walk.amp, P.run.amp]) for (const part of ['legL', 'legR', 'armL', 'armR'] as const) for (const f of phases) {
    const a = ppAngles(part, amp, f), b = ppAngles(part, amp, f, false);
    assert.ok(a.root === b.root && a.joint === b.joint, `${part} amp ${amp} φ ${f}`);
  }
});

